  ('4dc05e6e-0f84-4d83-a84b-9e0af5a0f40d', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', 'b58abda4-6df0-45cb-bb8c-d2a7e5e364fe', 'subtopic'::public.curated_course_node_type, 'UX vocabulary', 'Shared language makes critique and collaboration sharper.', 2),
