  ('ae0e5330-a8b0-4ee5-8475-88e83aaea3ab', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '4dc05e6e-0f84-4d83-a84b-9e0af5a0f40d', 'concept'::public.curated_course_node_type, 'Prototype fidelity', null, 1),
  ('54e9c7da-270d-417c-b2f5-4a9824a012c8', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '4dc05e6e-0f84-4d83-a84b-9e0af5a0f40d', 'concept'::public.curated_course_node_type, 'Heuristics and affordances', null, 2),
