  ('e7a3e178-c046-48b2-aea4-3c8ab14d25f3', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', 'b929d473-055f-4dcf-abf1-4516aae66c85', 'concept'::public.curated_course_node_type, 'Problem framing', null, 0),
