  ('2b56f37d-d782-4f35-b1ec-111b34cc1e27', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', 'b929d473-055f-4dcf-abf1-4516aae66c85', 'concept'::public.curated_course_node_type, 'Assumptions and risks', null, 2),
  ('0184fdc8-95ee-4d91-a5b8-33eb54ab8928', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '33dbb778-8f54-4721-ac84-90b1155c57d4', 'subtopic'::public.curated_course_node_type, 'Stakeholder mapping', 'The gist is to understand who influences, funds, builds, uses, and is affected by the product.', 1),
