  ('512aef46-c44b-4ce6-8b70-4f1ae9c225b1', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '0184fdc8-95ee-4d91-a5b8-33eb54ab8928', 'concept'::public.curated_course_node_type, 'Power and interest mapping', null, 1),
  ('a75eca56-a8d4-4f39-b73c-ae79a157010f', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '0184fdc8-95ee-4d91-a5b8-33eb54ab8928', 'concept'::public.curated_course_node_type, 'Conflicting goals', null, 2),
