  ('bfd915f4-4169-4d4b-a4be-84debb112e59', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', 'f3d4b5f6-aa94-404e-9318-a3b11f8efbda', 'concept'::public.curated_course_node_type, 'Business or mission outcomes', null, 1),
