  ('4b28aff5-5406-4199-a604-0af89707fdaf', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '8a1d79f7-0d02-4044-b73d-25a2c053bc18', 'concept'::public.curated_course_node_type, 'Generative versus evaluative research', null, 0),
  ('21ea05e9-f46b-4924-b5a6-e24330142436', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '8a1d79f7-0d02-4044-b73d-25a2c053bc18', 'concept'::public.curated_course_node_type, 'Behavior versus attitude', null, 1),
