  ('1653d898-8e5d-4ea6-a757-67a70c94f3ed', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '768846ad-b923-49d7-ab2c-d66daf7a7c38', 'concept'::public.curated_course_node_type, 'Privacy and data minimization', null, 1),
  ('48f5d252-4af0-4947-878f-d1cda27a5ea9', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '768846ad-b923-49d7-ab2c-d66daf7a7c38', 'concept'::public.curated_course_node_type, 'Power, vulnerability, and inclusion', null, 2),
  ('b3d6bb79-736d-4598-b27b-ec59a7cf8ede', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', null, 'topic'::public.curated_course_node_type, 'Qualitative Research: Interviews, Observation, and Fieldwork', 'Qualitative research helps designers understand context, motivations, pain points, and workarounds. Students practice asking, watching, listening, and documenting.', 3);
