  ('68f7ec18-531a-43f7-a62a-a10cfc609f9f', 'a3b4c5d6-7e8f-4a71-8c01-1d2e3f4a5b81', '9be9e50d-2834-472a-b7e2-f13d77ef9836', 'concept'::public.curated_course_node_type, 'Debriefs and research repositories', null, 2),
